// План specs/admin-plans.md, 1.3 (кейс AP-02). Только чтение. @prod-safe
import { test, expect } from '@playwright/test';
import { setLanguage, openPlansTab, TARGET_EMAIL } from './plans-helpers';
import { accountRows, loadedRowCount, searchBox, expectAllRowsContain } from './plans-read-helpers';

test.use({ storageState: '../auth/admin.json' });

test.describe('Admin Panel — Plans', () => {
  test('Search finds account by partial email, any case, Hebrew name and with surrounding spaces #ca557707 @desktop @prod-safe', async ({ page }) => {
    await setLanguage(page, 'en');
    await openPlansTab(page);
    const total = await loadedRowCount(page);
    const search = searchBox(page);

    for (const query of ['wojeg', 'WOJEG27104', 'בדיקה', '  wojeg  ']) {
      await test.step(`поиск «${query}»`, async () => {
        await search.fill(query);
        await expect(accountRows(page).filter({ hasText: TARGET_EMAIL })).toHaveCount(1);
        await expectAllRowsContain(page, query);
      });
    }

    await search.fill('');
    await expect(accountRows(page)).toHaveCount(total);
  });
});
